window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[304]={"id":"304","numero":304,"titre":"Tumeurs du foie, primitives et secondaires","objectifs":[{"id":"304-1","rang":"B","rubrique":"Définition","titre":"Connaître les principaux types histologiques des tumeurs bénignes et malignes","contenu":"<p>Les tumeurs hépatiques sont des <span class=\"kw-def\">nodules tissulaires de nature différente du parenchyme adjacent</span>. <span class=\"kw-alerte\">Attention pédagogique</span> : le kyste biliaire simple et les lésions infectieuses ne sont pas comptés comme des tumeurs hépatiques en HGE.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Bénignes non infectieuses</th>\n            <th>Bénignes infectieuses</th>\n            <th>Malignes</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong>Kyste biliaire simple</strong> ; <strong>Hémangiome</strong> (angiome) ; <span class=\"kw-etio\">Hyperplasie nodulaire focale (HNF)</span> ; <span class=\"kw-etio\">Adénome hépatocytaire</span>\n            </td>\n            <td>\n              Abcès à pyogènes (rare) ; Abcès amibien ; Kyste hydatique ; Échinococcose alvéolaire\n            </td>\n            <td>\n              <span class=\"kw-etio\">Métastases hépatiques</span> (les plus fréquentes) ; <span class=\"kw-etio\">CHC</span> (cancer primitif le plus fréquent) ; <span class=\"kw-etio\">Cholangiocarcinome</span> (2ᵉ cancer primitif)<br>\n              <strong>Tumeurs exceptionnelles :</strong> <span class=\"kw-alerte\">hépato-cholangiocarcinome</span> (très mauvais pronostic) ; hépatoblastome (pédiatrique) ; hémangio-endothéliome épithélioïde ; <span class=\"kw-alerte\">angiosarcome primitif</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Ordre de fréquence à retenir.</strong> Hémangiome bénin &gt; Métastases hépatiques &gt; CHC &gt; HNF &gt; Adénome hépatocellulaire &gt; Cholangiocarcinome.\n      </div>","frequence":1},{"id":"304-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence et l’épidémiologie des différentes tumeurs bénignes et malignes du foie","contenu":"<p>Les tumeurs du foie touchent environ <span class=\"kw-chiffre\">5 %</span> de la population. Hégémonie des tumeurs bénignes, le plus souvent asymptomatiques et découvertes fortuitement à l'imagerie.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Entité</th>\n            <th>Prévalence</th>\n            <th>Sex-ratio</th>\n            <th>Particularité</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Kyste biliaire</td>\n            <td><span class=\"kw-chiffre\">5 %</span></td>\n            <td>—</td>\n            <td>Le plus fréquent des bénins</td>\n          </tr>\n          <tr>\n            <td>Hémangiome</td>\n            <td><span class=\"kw-chiffre\">3-5 %</span></td>\n            <td>Féminin</td>\n            <td>2ᵉ bénin par fréquence</td>\n          </tr>\n          <tr>\n            <td>HNF</td>\n            <td><span class=\"kw-chiffre\">0,1-1 %</span></td>\n            <td>Féminin (femme jeune)</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td>Adénome hépatocytaire</td>\n            <td><span class=\"kw-chiffre\">0,01-0,1 %</span></td>\n            <td>Féminin (<span class=\"kw-chiffre\">75 %</span>)</td>\n            <td><span class=\"kw-alerte\">Risque de dégénérescence + hémorragique</span></td>\n          </tr>\n          <tr>\n            <td>CHC</td>\n            <td><span class=\"kw-chiffre\">10 500 cas/an</span> France ; <span class=\"kw-chiffre\">3 %</span> de tous les cancers ; <span class=\"kw-chiffre\">8 000</span> nouveaux cas/an ; <span class=\"kw-chiffre\">8 700 décès/an</span></td>\n            <td>Masculin <span class=\"kw-chiffre\">6:1</span></td>\n            <td><span class=\"kw-alerte\">Sur cirrhose dans 90 % des cas</span> en Occident</td>\n          </tr>\n          <tr>\n            <td>Cholangiocarcinome</td>\n            <td><span class=\"kw-chiffre\">3 000 cas/an</span> France ; intra-hépatique &lt; <span class=\"kw-chiffre\">1 000 cas/an</span> (<span class=\"kw-chiffre\">7-8×</span> moins fréquent que CHC)</td>\n            <td>—</td>\n            <td><span class=\"kw-alerte\">Pronostic mauvais</span> : survie <span class=\"kw-chiffre\">30-40 %</span> à<span class=\"kw-chiffre\"> 5 ans</span> même curatif</td>\n          </tr>\n          <tr>\n            <td>Métastases hépatiques</td>\n            <td>Tumeurs malignes les plus fréquentes du foie</td>\n            <td>—</td>\n            <td>Révélatrices/synchrones dans <span class=\"kw-chiffre\">25 %</span> des cas</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers</em></p>","frequence":0},{"id":"304-3","rang":"A","rubrique":"Étiologies","titre":"Connaître la liste des principales hépatopathies augmentant le risque de survenue ultérieure d’un cancer primitif du foie","contenu":"<p>Le CHC se développe sur une <span class=\"kw-def\">maladie chronique du foie</span> dans <span class=\"kw-chiffre\">90 %</span> des cas en Occident — c'est la donnée pivot de l'item.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Hépatopathie</th>\n            <th>Mécanisme + Risque</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Cirrhose hépatique</span> (toute cause)</td>\n            <td>Risque <span class=\"kw-chiffre\">2 à 5 %/an</span>, soit <span class=\"kw-chiffre\">5-30 %</span> à<span class=\"kw-chiffre\"> 5 ans</span>. <span class=\"kw-etio\">Alcool</span>-VHC prédominent en Europe ; VHB en Afrique-Asie. <strong>Attention</strong> : le risque <span class=\"kw-alerte\">persiste même après contrôle/éradication</span> de la cause → dépistage à poursuivre</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Hépatite virale B chronique</span></td>\n            <td>Peut donner CHC <span class=\"kw-alerte\">sans cirrhose préalable</span> ⚠️</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Hépatite virale C chronique</span></td>\n            <td>Risque via <span class=\"kw-etio\">cirrhose</span> post-VHC (Europe ++)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Consommation chronique d'alcool</span></td>\n            <td>Risque via <span class=\"kw-etio\">cirrhose</span> alcoolique (Europe ++)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Hémochromatose</span></td>\n            <td>Surcharge en fer hépatique ; peut donner CHC <span class=\"kw-alerte\">sans cirrhose préalable</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Stéato-hépatite métabolique (NASH)</span></td>\n            <td>Peut donner CHC <span class=\"kw-alerte\">sans cirrhose préalable</span> ⚠️</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Toxines alimentaires</span></td>\n            <td><strong>Aflatoxine</strong> (farines, arachides) ; <strong>Lutéoskyrine</strong> (riz) — exposition essentiellement extra-européenne</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Drapeau rouge.</strong> Le dépistage du CHC (écho + <span class=\"kw-bio\">AFP</span> /<span class=\"kw-chiffre\">6 mois</span>) doit être poursuivi <span class=\"kw-alerte\">même après éradication virale ou sevrage alcoolique</span> chez tout patient cirrhotique — le risque persiste malgré le contrôle étiologique.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-etio\">Cirrhose</span> · 167 — Hépatites virales · 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 219 — Pathologie du fer</em></p>","frequence":1},{"id":"304-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique initiale","contenu":"<p>Trois circonstances de découverte d'une tumeur hépatique : <span class=\"kw-clinique\">signes cliniques</span> (douleurs, hépatomégalie) ; <span class=\"kw-bio\">anomalies du bilan hépatique</span> (transaminases, <span class=\"kw-bio\">bilirubine</span>, <span class=\"kw-bio\">AFP</span>) ; <span class=\"kw-imagerie\">découverte fortuite</span> en imagerie (écho, <span class=\"kw-imagerie\">TDM</span>, <span class=\"kw-imagerie\">IRM</span>).</p>\n\n      <p><strong>Question pivot</strong> : « Le patient a-t-il une <span class=\"kw-def\">maladie chronique du foie</span> ? » — évaluation par examen clinique + bilan biologique + <span class=\"kw-imagerie\">échographie</span> + élastométrie (Fibroscan).</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Contexte</th>\n            <th>Démarche</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Cirrhose</span> / hépatopathie chronique connue</strong></td>\n            <td><span class=\"kw-imagerie\">Scanner OU IRM hépatique multiphasique</span>. Deux hypothèses : <span class=\"kw-etio\">CHC</span> (le plus fréquent) ou autre tumeur (rare). Si critères AASLD-EASL réunis (nodule &gt; <span class=\"kw-chiffre\">1 cm</span> + wash-in + wash-out + <span class=\"kw-etio\">cirrhose</span> certaine + validation RCP) → diagnostic <span class=\"kw-alerte\">sans biopsie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Absence d'hépatopathie chronique</strong></td>\n            <td><span class=\"kw-imagerie\">Scanner OU IRM hépatique multiphasique</span> avec gamme diagnostique large : angiome ; métastase ; HNF ; CHC (moins fréquent sans <span class=\"kw-etio\">cirrhose</span>) ; cholangiocarcinome ; adénome hépatique. Si imagerie non concluante → <span class=\"kw-bio\">biopsie</span> de la lésion</td>\n          </tr>\n          <tr>\n            <td><strong>Tumeur chez patient suivi pour cancer</strong></td>\n            <td>Hypothèse 1 = <span class=\"kw-etio\">métastase hépatique</span>. <span class=\"kw-bio\">Biopsie</span> nécessaire si : imagerie peu caractéristique OU lésion métachrone &gt;<span class=\"kw-chiffre\"> 2 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Découverte fortuite, lésion kystique</strong></td>\n            <td>Éliminer kyste biliaire simple (pas de paroi, pas de cloison, parfaitement liquidien). Sérologies hydatidose si zone d'endémie + contact chien</td>\n          </tr>\n          <tr>\n            <td><strong>Découverte fortuite, tumeur solide</strong></td>\n            <td>Préciser la cinétique du produit de contraste (cf. obj-4 stratégie imagerie)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège <span class=\"kw-bio\">AFP</span>.</strong> Le dosage de l'<span class=\"kw-bio\">α-fœto-protéine (AFP)</span> n'est <span class=\"kw-alerte\">PAS un examen diagnostique</span> du CHC — c'est un marqueur pronostique. La démarche diagnostique repose sur l'imagerie (± <span class=\"kw-bio\">biopsie</span>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 279 — <span class=\"kw-etio\">Cirrhose</span></em></p>","frequence":3},{"id":"304-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la stratégie d’exploration en imagerie devant une tumeur du foie","contenu":"<p>L'imagerie multiphasique (<span class=\"kw-imagerie\">TDM ou IRM avec 4 temps</span> : sans injection, artériel, portal, tardif) est le pilier diagnostique des tumeurs hépatiques. Le CHC est vascularisé <span class=\"kw-alerte\">exclusivement par l'artère hépatique</span>, contrairement au parenchyme normal qui reçoit aussi la veine porte — ce qui explique le wash-in artériel et le wash-out portal des lésions hépatocytaires malignes.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Caractéristique</th>\n            <th>Kyste biliaire</th>\n            <th>Hémangiome</th>\n            <th>HNF</th>\n            <th>Adénome</th>\n            <th>CHC</th>\n            <th>Cholangiocarcinome</th>\n            <th>Métastases</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Écho</strong></td>\n            <td>Anéchogène ; cône de renforcement postérieur</td>\n            <td>Hyperéchogène ; renforcement postérieur (peut suffire au diag ✅)</td>\n            <td>Iso/hypoéchogène (diag difficile en écho)</td>\n            <td>Hétérogène ; bien limité ; hypoéchogène</td>\n            <td>Nodule &gt; <span class=\"kw-chiffre\">1 cm</span> ; hétérogène (plages hyper + hypoéchogènes) ; extension/obstruction porte</td>\n            <td>Syndrome de masse ; dilatation des voies biliaires d'amont</td>\n            <td>Hypoéchogène en cocardes</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> non injecté</strong></td>\n            <td>Hypodense</td>\n            <td>Homogène, hypodense</td>\n            <td>Hypodense</td>\n            <td>Hypodense</td>\n            <td>Iso/hypodense</td>\n            <td>—</td>\n            <td>Hypodense spontanément</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> artériel</strong></td>\n            <td>Inchangé</td>\n            <td>Remplissage en mottes périphériques</td>\n            <td><span class=\"kw-imagerie\">Réhaussement intense</span> ; cicatrice centrale non/peu réhaussée</td>\n            <td><span class=\"kw-imagerie\">Wash-in</span></td>\n            <td><span class=\"kw-imagerie\">Wash-in</span> (hyperdensité)</td>\n            <td>Prise de contraste progressive (réaction desmoplastique)</td>\n            <td><span class=\"kw-alerte\">Pas de réhaussement</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> portal</strong></td>\n            <td>Inchangé</td>\n            <td>Remplissage centripète (mottes → centre)</td>\n            <td>Lavage progressif</td>\n            <td><span class=\"kw-imagerie\">Wash-out</span></td>\n            <td><span class=\"kw-imagerie\">Wash-out</span> (hypodensité)</td>\n            <td>Persistance de la prise de contraste</td>\n            <td>Couronne périphérique inconstante réhaussée</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IRM</span></strong></td>\n            <td>HyperT2 franc</td>\n            <td>HypoT1, hyperT2 ; remplissage en mottes centripète</td>\n            <td>Réhaussement intense + cicatrice centrale hyperT2</td>\n            <td>HypoT1, hyperT2 ; réhaussement hétérogène artériel</td>\n            <td>Wash-in/wash-out idem <span class=\"kw-imagerie\">TDM</span></td>\n            <td><span class=\"kw-imagerie\">TDM</span>/bili-<span class=\"kw-imagerie\">IRM</span> = référence</td>\n            <td>Plus sensible que <span class=\"kw-imagerie\">TDM</span> (utile après chimio)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Biopsie</span></strong></td>\n            <td><span class=\"kw-ci\">Non</span></td>\n            <td><span class=\"kw-ci\">Contre-indiquée</span> (risque <span class=\"kw-etio\">hémorragique</span>)</td>\n            <td>Possible si doute</td>\n            <td>Nécessaire</td>\n            <td>Nécessaire <strong>sauf</strong> si critères AASLD-EASL réunis</td>\n            <td>Systématique (adénocarcinome)</td>\n            <td>Inutile si primitif connu + métastase &lt;<span class=\"kw-chiffre\"> 2 ans</span> + imagerie compatible</td>\n          </tr>\n          <tr>\n            <td><strong>PEC</strong></td>\n            <td>Aucune (sauf complication mécanique → fenestration)</td>\n            <td>Aucune (ne dégénère jamais)</td>\n            <td>Aucune (ne se complique jamais)</td>\n            <td>Chirurgie si &gt; <span class=\"kw-chiffre\">5 cm</span>, homme, mutation β-caténine ; surveillance + arrêt œstrogènes sinon</td>\n            <td>Curatif (résection, ablation, transplantation) <span class=\"kw-bio\">vs</span> palliatif</td>\n            <td>Résection si possible + chimio</td>\n            <td>Dépend du primitif</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Mnémo wash-in / wash-out.</strong> Deux entités font du <span class=\"kw-imagerie\">wash-in artériel + wash-out portal</span> : <span class=\"kw-etio\">CHC</span> et <span class=\"kw-etio\">Adénome</span> (les 2 lésions hépatocytaires). L'<span class=\"kw-etio\">HNF</span> a un wash-in intense MAIS pas de wash-out (lavage progressif). L'hémangiome a un remplissage en mottes centripète, pas de wash-out.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège — métastases hypervascularisées.</strong> Certaines métastases (<span class=\"kw-etio\">TNE</span>, rénales, mélanome, thyroïde) peuvent se réhausser au temps artériel — la règle « pas de réhaussement » ne vaut que pour les métastases <span class=\"kw-alerte\">hypovascularisées</span> (adénocarcinomes digestifs).\n      </div>","frequence":7},{"id":"304-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique positive d’une métastase hépatique","contenu":"<p>Les métastases hépatiques sont <strong>les tumeurs malignes les plus fréquentes du foie</strong>. Elles sont révélatrices ou synchrones du cancer primitif dans <span class=\"kw-chiffre\">25 %</span> des cas.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Étape</th>\n            <th>Conduite</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Identification</strong></td>\n            <td>Tumeur(s) hépatique(s) suspecte(s) sur données <span class=\"kw-clinique\">cliniques</span>, <span class=\"kw-bio\">biologiques</span>, <span class=\"kw-imagerie\">radiologiques</span></td>\n          </tr>\n          <tr>\n            <td><strong>2. ATCD de cancer</strong></td>\n            <td>Cancer récent &lt;<span class=\"kw-chiffre\"> 2-3 ans</span> OU cancer récemment diagnostiqué → suspicion forte de métastase. Penser aux cancers synchrones et métachrones</td>\n          </tr>\n          <tr>\n            <td><strong>3. Recherche du primitif</strong></td>\n            <td>Cancers primitifs par ordre de fréquence : <span class=\"kw-etio\">adénocarcinomes digestifs</span> (estomac, pancréas, côlon, rectum) &gt; poumon &gt; sein &gt; <span class=\"kw-etio\">carcinomes anaplasiques</span> &gt; mélanomes &gt; <span class=\"kw-etio\">TNE</span> &gt; autres (VADS, sarcomes, testicule, œsophage, anus)</td>\n          </tr>\n          <tr>\n            <td><strong>4. Diag sans <span class=\"kw-bio\">biopsie</span></strong></td>\n            <td>Conditions cumulatives : tumeur primitive connue (avec preuve anapath) + délai <span class=\"kw-chiffre\">&lt; 2 ans</span> (synchrone ou métachrone) + imagerie compatible</td>\n          </tr>\n          <tr>\n            <td><strong>5. <span class=\"kw-bio\">Biopsie</span> indispensable</strong></td>\n            <td>Lésion métachrone &gt;<span class=\"kw-chiffre\"> 2 ans</span> ; imagerie peu caractéristique ; primitif non connu ; 2 cancers primitifs différents dans les ATCD ; recherche d'une mutation à portée thérapeutique non faisable sur le primitif (ex : RAS/RAF sur métastases <span class=\"kw-etio\">CCR</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Aucun primitif retrouvé</strong></td>\n            <td>&lt; <span class=\"kw-chiffre\">10 %</span> des cas malgré bilan complet adapté à l'anapath</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p>Le <span class=\"kw-alerte\">caractère multiple</span> est un argument fort en faveur de métastases, a fortiori avec d'autres métastases ailleurs (poumon, os, péritoine). L'aspect varie selon la tumeur primitive — tous les aspects sont possibles, y compris kystique (<span class=\"kw-etio\">TNE</span> par exemple).</p>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège délai.</strong> Au-delà de <span class=\"kw-chiffre\">2 ans</span> entre le primitif et la métastase, la <span class=\"kw-bio\">biopsie</span> redevient indispensable même si l'imagerie semble compatible — risque d'un 2ᵉ cancer primitif méconnu.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum · 303 — Tumeur estomac · 305 — Tumeur de l'œsophage · 308 — Tumeur pancréas · 309 — Tumeurs du poumon</em></p>","frequence":0},{"id":"304-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la présentation clinique d’une tumeur primitive du foie","contenu":"<p>Le CHC touche le sujet de <span class=\"kw-chiffre\">&gt; 45 ans</span>, à prédominance masculine (sex-ratio <span class=\"kw-chiffre\">6:1</span>), <span class=\"kw-alerte\">sur cirrhose dans 90 % des cas</span> en Occident.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Catégorie</th>\n            <th>Manifestations</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Circonstance — dépistage</strong></td>\n            <td><span class=\"kw-etio\">Cirrhose</span> : <span class=\"kw-imagerie\">écho abdominale</span> + <span class=\"kw-bio\">α-fœto-protéine</span> tous les <span class=\"kw-chiffre\">6 mois</span>. <span class=\"kw-etio\">Hépatite</span> B sans <span class=\"kw-etio\">cirrhose</span> : écho abdo tous les <span class=\"kw-chiffre\">2 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Signes fonctionnels</strong></td>\n            <td><span class=\"kw-clinique\">Douleurs hypochondre droit</span> ; <span class=\"kw-clinique\">pesanteur épigastrique</span> ; <span class=\"kw-clinique\">AEG</span> (<span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">anorexie</span>, <span class=\"kw-clinique\">amaigrissement</span>) ; <span class=\"kw-clinique\">fièvre</span> ; <span class=\"kw-clinique\">anémie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Signes physiques</strong></td>\n            <td><span class=\"kw-clinique\">Hépatomégalie</span> ferme nodulaire ; <span class=\"kw-clinique\">ictère</span> ; <span class=\"kw-clinique\">ascite</span></td>\n          </tr>\n          <tr>\n            <td><strong>Décompensation de <span class=\"kw-etio\">cirrhose</span></strong></td>\n            <td><span class=\"kw-alerte\">Décompensation œdémato-ascitique</span> ; <span class=\"kw-alerte\">hémorragie digestive</span> par rupture de varices œsophagiennes ; aggravation IHC + HTP connues</td>\n          </tr>\n          <tr>\n            <td><strong>Syndrome <span class=\"kw-etio\">paranéoplasique</span></strong></td>\n            <td><span class=\"kw-bio\">Polyglobulie</span> (sécrétion EPO) ; <span class=\"kw-bio\">hypoglycémie</span> (sécrétion <span class=\"kw-ttt\">insuline</span>) ; <span class=\"kw-bio\">hypercalcémie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Dissémination</strong></td>\n            <td>Essentiellement intra-hépatique via les vaisseaux → <span class=\"kw-alerte\">thrombose portale tumorale</span> ++ ; explique les récidives locales et la multifocalité</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Mode de révélation typique.</strong> Toute <span class=\"kw-alerte\">décompensation aiguë</span> chez un cirrhotique connu (œdémato-ascitique, hémorragie digestive, encéphalopathie) doit faire évoquer un CHC sous-jacent comme facteur déclenchant — réflexe à acquérir.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-etio\">Cirrhose</span></em></p>","frequence":1},{"id":"304-8","rang":"B","rubrique":"Contenu multimédia","titre":"Tomodensitométrie typique de métastases hépatiques","contenu":"<p>Les métastases hépatiques sont la <strong>pathologie maligne du foie la plus fréquente</strong>. La <span class=\"kw-imagerie\">TDM avec injection multiphasique</span> reste l'examen de référence pour leur caractérisation.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Temps <span class=\"kw-imagerie\">TDM</span></th>\n            <th>Sémiologie</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Avant injection</strong></td>\n            <td>Lésions spontanément <span class=\"kw-imagerie\">hypodenses</span> par rapport au parenchyme hépatique normal</td>\n          </tr>\n          <tr>\n            <td><strong>Temps artériel</strong></td>\n            <td><span class=\"kw-alerte\">Pas de réhaussement</span> (cas typique des métastases hypovascularisées d'origine digestive)</td>\n          </tr>\n          <tr>\n            <td><strong>Temps portal</strong></td>\n            <td><span class=\"kw-imagerie\">Couronne périphérique</span> inconstante réhaussée ; centre hypodense ; bords mal limités</td>\n          </tr>\n          <tr>\n            <td><strong>Caractère multiple</strong></td>\n            <td>Argument fort en faveur du diagnostic, a fortiori s'il existe d'autres métastases ailleurs (poumon, os, péritoine)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p>L'aspect peut varier selon le primitif — certaines métastases sont <span class=\"kw-alerte\">hypervascularisées</span> (<span class=\"kw-etio\">TNE</span>, mélanome, rein, thyroïde) avec réhaussement artériel franc. Toujours croiser avec le contexte clinique et le primitif suspecté.</p>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/304/tdm-metastases-hepatiques.png\" alt=\"TDM abdomino-pelvienne avec injection : à gauche métastases hépatiques « classiques » hypodenses au temps portal, à droite métastases hypervascularisées rehaussées au temps artériel\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM abdomino-pelvienne</span> avec injection — <span class=\"kw-etio\">métastases hépatiques</span>. <strong>Classiques :</strong> lésions <span class=\"kw-radio\">discrètement rehaussées de façon hétérogène au temps portal, plutôt en périphérie, restant hypodenses</span> par rapport au parenchyme. <strong>Hyper-rehaussées :</strong> rehaussement au temps artériel supérieur au parenchyme (cancer du rein, thyroïde, mélanome, <span class=\"kw-alerte\">tumeur neuro-endocrine</span>). Source : banque imagerie « Imagerie à connaître » (planche partagée items 276/304).</figcaption>\n      </figure>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/liver-tumours","label":"Radiopaedia : Liver tumours"},{"href":"https://radiopaedia.org/articles/simple-hepatic-cyst","label":"Radiopaedia : Simple hepatic cyst"},{"href":"https://radiopaedia.org/articles/hepatic-haemangioma-3","label":"Radiopaedia : Hepatic haemangioma 3"},{"href":"https://radiopaedia.org/articles/hepatocellular-carcinoma","label":"Radiopaedia : Hepatocellular carcinoma"},{"href":"https://radiopaedia.org/articles/hepatic-metastases-1","label":"Radiopaedia : Hepatic metastases 1"},{"href":"https://radiopaedia.org/articles/cholangiocarcinoma","label":"Radiopaedia : Cholangiocarcinoma"}]},{"id":"304-9","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie et les facteurs de risque des tumeurs biliaires","contenu":"<p>Les tumeurs biliaires sont presque toujours <strong>malignes</strong> (sauf exceptions rares), principalement primitives, représentées par le <span class=\"kw-etio\">cholangiocarcinome (CCA)</span>.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Type anatomique</th>\n            <th>Caractéristiques</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>CCA intra-hépatique</strong></td>\n            <td>Cholangiocytes tapissant les canaux biliaires <strong>intra-parenchymateux</strong>. Souvent <span class=\"kw-clinique\">paucisymptomatique</span> au début. FR : maladie chronique du foie ± <span class=\"kw-etio\">cirrhose</span></td>\n          </tr>\n          <tr>\n            <td><strong>CCA extra-hépatique</strong></td>\n            <td>Cholangiocytes de la voie biliaire extra-hépatique. Tumeur mal limitée s'étendant le long des canaux. Atteinte fréquente de la voie biliaire haute = <span class=\"kw-etio\">cholangiocarcinome hilaire</span> ou <span class=\"kw-etio\">tumeur de Klatskin</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Facteur de risque</th>\n            <th>Commentaire</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>De novo sur foie sain</strong></td>\n            <td><span class=\"kw-alerte\">Majorité des CCA</span> surviennent sans FR identifié — contrairement au CHC</td>\n          </tr>\n          <tr>\n            <td><strong>Maladie chronique du foie</strong> (<span class=\"kw-etio\">cirrhose</span> ou non)</td>\n            <td>FR de <span class=\"kw-etio\">CCA intra-hépatique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Cholangite sclérosante primitive (CSP)</strong></td>\n            <td>FR majeur de <span class=\"kw-etio\">CCA péri-hilaire et extra-hépatique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Parasitoses biliaires</strong></td>\n            <td>Distomatose (Asie ++) ; opisthorchiase</td>\n          </tr>\n          <tr>\n            <td><strong>Lithiase intra-hépatique</strong></td>\n            <td>Fréquente en Asie : <span class=\"kw-chiffre\">10 %</span> des patients développent un CCA</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p>Vascularisation du CCA : <span class=\"kw-imagerie\">double — artère hépatique + veine porte</span> (différente du CHC), avec <span class=\"kw-def\">réaction desmoplastique</span> (fibrose abondante) — explique le pattern de prise de contraste progressive aux 2 temps.</p>\n\n      <div class=\"callout callout-warn\">\n        <strong>Aucun marqueur tumoral spécifique du CCA.</strong> Le <span class=\"kw-bio\">CA 19-9</span> peut être élevé mais n'est <span class=\"kw-alerte\">pas demandé pour le diagnostic</span> de manière isolée — la <span class=\"kw-bio\">biopsie</span> est systématique (adénocarcinome à différenciation biliaire).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 277 — Lithiase biliaire</em></p>","frequence":1},{"id":"304-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la présentation clinique des tumeurs biliaires","contenu":"<p>Le CCA représente <span class=\"kw-chiffre\">3 000 cas/an</span> en France, avec un <span class=\"kw-alerte\">pronostic mauvais</span> — survie <span class=\"kw-chiffre\">30-40 %</span> à<span class=\"kw-chiffre\"> 5 ans</span> même en situation curative.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Mode de découverte</th>\n            <th>Manifestations</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Découverte fortuite</strong></td>\n            <td>Le plus souvent sur imagerie réalisée pour autre raison (CCA intra-hépatique surtout)</td>\n          </tr>\n          <tr>\n            <td><strong>Signes généraux</strong></td>\n            <td><span class=\"kw-clinique\">AEG</span> ; <span class=\"kw-clinique\">fièvre</span> ; <span class=\"kw-clinique\">hépatalgie</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Ictère</span> cholestatique</strong></td>\n            <td><span class=\"kw-alerte\">Ictère à bilirubine conjuguée</span> (CCA extra-hépatique surtout) — triade : <span class=\"kw-clinique\">prurit + selles décolorées + urines foncées</span></td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie 1ʳᵉ ligne</strong></td>\n            <td><span class=\"kw-imagerie\">Échographie</span> évoque le diag : <span class=\"kw-imagerie\">syndrome de masse hépatique</span> + <span class=\"kw-imagerie\">dilatation des voies biliaires d'amont</span></td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie de référence</strong></td>\n            <td><span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">IRM</span> injectée — notamment <span class=\"kw-imagerie\">bili-IRM</span> : prise de contraste progressive aux 2 temps (artériel + veineux)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-clinique\">Ictère</span> + dilatation VB = obstacle.</strong> Tout <span class=\"kw-alerte\">ictère cholestatique à bilirubine conjuguée</span> avec <span class=\"kw-imagerie\">dilatation des voies biliaires</span> doit faire évoquer un obstacle tumoral — le CCA hilaire (tumeur de Klatskin) est le diagnostic à éliminer en priorité chez l'adulte &gt;<span class=\"kw-chiffre\"> 50 ans</span>.\n      </div>","frequence":0},{"id":"304-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge des principales tumeurs bénignes et malignes du foie","contenu":"<p>La prise en charge est <strong>adaptée à l'histologie</strong> et au terrain hépatique sous-jacent, avec discussion systématique en <span class=\"kw-def\">RCP</span>.</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Entité</th>\n            <th>Principes de PEC</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Tumeurs bénignes</strong> (kyste, hémangiome, HNF)</td>\n            <td>Aucun traitement, aucune surveillance dans le cas général. <strong>Exception kyste</strong> : <span class=\"kw-ttt\">fenestration chirurgicale</span> si complication mécanique</td>\n          </tr>\n          <tr>\n            <td><strong>Adénome hépatocytaire</strong></td>\n            <td><span class=\"kw-alerte\">Chirurgie formelle</span> si : taille &gt; <span class=\"kw-chiffre\">5 cm</span> (risque hémorragie/rupture/dégénérescence) ; sexe masculin (risque de complication ++) ; mutation β-caténine (risque de transformation maligne).<br><strong>Si &lt; <span class=\"kw-chiffre\">5 cm</span> chez femme</strong> : <span class=\"kw-ttt\">arrêt des œstrogènes</span> (COP) systématique + surveillance <span class=\"kw-imagerie\">IRM</span> annuelle</td>\n          </tr>\n          <tr>\n            <td><strong>CHC</strong></td>\n            <td><strong>Bilan d'extension</strong> : écho + <span class=\"kw-imagerie\">TDM</span> hépatique systématique ± <span class=\"kw-imagerie\">IRM</span> ; <span class=\"kw-imagerie\">RXT</span> systématique ; scinti osseuse si point d'appel. <strong>Marqueurs</strong> : <span class=\"kw-bio\">α-fœto-protéine</span> ± <span class=\"kw-bio\">gammacarboxyprothrombine</span>.<br><strong>Curatifs</strong> : <span class=\"kw-ttt\">ablation percutanée</span> ; <span class=\"kw-ttt\">résection chirurgicale</span> ; <span class=\"kw-ttt\">transplantation hépatique</span> (traite cancer + maladie chronique).<br><strong>Palliatifs</strong> : <span class=\"kw-ttt\">chimio-embolisation artérielle</span> ; thérapies anti-angiogéniques ciblées ; immunothérapie ; soins de confort</td>\n          </tr>\n          <tr>\n            <td><strong>Cholangiocarcinome</strong></td>\n            <td><span class=\"kw-ttt\">Résection chirurgicale + chimio adjuvante</span> = seul traitement curatif. Si non résécable : chimio ± radiothérapie. Palliatif : chimio + drainage de la bile (<span class=\"kw-ttt\">CPRE + prothèse</span> ou drain) pour traiter <span class=\"kw-clinique\">ictère</span>/<span class=\"kw-clinique\">prurit</span></td>\n          </tr>\n          <tr>\n            <td><strong>Métastases hépatiques</strong></td>\n            <td>Dépend du primitif — le plus souvent thérapie systémique ou traitement palliatif. <strong>Cas favorable</strong> : métastases hépatiques de <span class=\"kw-etio\">CCR</span> = les plus accessibles à un traitement curatif (<span class=\"kw-ttt\">chirurgie hépatique + chimio</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>3 piliers thérapeutiques du CHC à retenir.</strong> <span class=\"kw-ttt\">Ablation percutanée</span> (radiofréquence/micro-ondes) — <span class=\"kw-ttt\">Résection chirurgicale</span> — <span class=\"kw-ttt\">Transplantation hépatique</span>. Cette dernière est le seul traitement qui adresse simultanément le cancer ET la maladie chronique du foie sous-jacente (<span class=\"kw-etio\">cirrhose</span>) — indication à connaître selon les critères de Milan.\n      </div>\n\n      <h5 style=\"margin-top: 1.2em;\">Classification BCLC du CHC</h5>\n      <p>La <span class=\"kw-def\">classification BCLC</span> (Barcelona Clinic Liver Cancer) est le système pronostique de référence international qui <strong>guide directement le choix thérapeutique</strong> du CHC. Elle intègre 3 paramètres : <span class=\"kw-clinique\">taille et nombre de nodules</span>, <span class=\"kw-bio\">fonction hépatique</span> (<span class=\"kw-def\">Child-Pugh</span>), <span class=\"kw-clinique\">état général</span> (Performance Status ECOG).</p>\n\n      <table >\n        <thead>\n          <tr>\n            <th>Stade BCLC</th>\n            <th>Critères</th>\n            <th>Traitement recommandé</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>0 — Très précoce</strong></td>\n            <td>Nodule unique <span class=\"kw-chiffre\">&lt; 2 cm</span> ; Child A ; PS 0</td>\n            <td><span class=\"kw-ttt\">Ablation percutanée</span> ou résection</td>\n          </tr>\n          <tr>\n            <td><strong>A — Précoce</strong></td>\n            <td>1 à 3 nodules <span class=\"kw-chiffre\">≤ 3 cm</span> ; Child A-B ; PS 0</td>\n            <td><span class=\"kw-ttt\">Résection</span>, <span class=\"kw-ttt\">transplantation</span> (critères de Milan) ou ablation</td>\n          </tr>\n          <tr>\n            <td><strong>B — Intermédiaire</strong></td>\n            <td>Multinodulaire sans invasion vasculaire ni méta ; Child A-B ; PS 0</td>\n            <td><span class=\"kw-ttt\">Chimio-embolisation artérielle</span> (TACE)</td>\n          </tr>\n          <tr>\n            <td><strong>C — Avancé</strong></td>\n            <td><span class=\"kw-alerte\">Invasion vasculaire</span> ou <span class=\"kw-alerte\">métastases extra-hépatiques</span> ; Child A-B ; PS 1-2</td>\n            <td><span class=\"kw-ttt\">Traitement systémique</span> (immunothérapie : atézolizumab + bévacizumab ; ou thérapies ciblées : sorafénib, lenvatinib)</td>\n          </tr>\n          <tr>\n            <td><strong>D — Terminal</strong></td>\n            <td>Child C ou PS 3-4</td>\n            <td><span class=\"kw-ttt\">Soins de support</span> exclusifs</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Mnémo BCLC.</strong> Les 3 lettres clés à mémoriser : <span class=\"kw-ttt\">A = curatif</span> (résection/transplantation/ablation), <span class=\"kw-ttt\">B = TACE</span> (chimio-embolisation), <span class=\"kw-ttt\">C = systémique</span> (immunothérapie/thérapies ciblées). Le stade 0 prolonge A vers le très précoce ; le stade D bascule en soins de support.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 294 — Traitement des cancers · 295 — Prise en charge d'un malade cancéreux · 139 — Soins palliatifs - repères cliniques - organisation hospitalière et ambulatoire</em></p>","frequence":3}],"astuces":[],"strategie":{"principes":"<p><strong>Règle d’or :</strong> la PEC dépend du <span class=\"kw-def\">type histologique</span> ; les tumeurs bénignes typiques (<span class=\"kw-def\">hémangiome</span>, <span class=\"kw-def\">HNF</span>, <span class=\"kw-def\">kyste biliaire</span>) ne nécessitent <strong>ni traitement ni surveillance</strong>. Toute tumeur maligne est discutée en <span class=\"kw-ttt\">RCP</span>.</p><p><strong>Tumeurs bénignes typiques <span class=\"q\">— hémangiome · HNF · kyste biliaire</span></strong></p><ul><li><span class=\"kw-ttt\">Abstention thérapeutique</span> : ne dégénèrent jamais, aucune surveillance</li><li><span class=\"kw-imagerie\">Biopsie</span> de l’hémangiome <span class=\"kw-ci\">contre-indiquée</span> (risque hémorragique)</li><li>Kyste biliaire : <span class=\"kw-ttt\">fenestration</span> seulement si complication mécanique</li></ul><p><strong>Adénome hépatocytaire <span class=\"q\">— risque de dégénérescence et de rupture</span></strong></p><p><span class=\"kw-ttt\">arrêt des œstrogènes</span> dans tous les cas</p><ul><li><span class=\"kw-ttt\">Chirurgie</span> si taille <span class=\"kw-chiffre\">&gt; 5 cm</span>, sexe masculin ou mutation β-caténine</li><li>Tumeur <span class=\"kw-chiffre\">&lt; 5 cm</span> chez la femme : surveillance par <span class=\"kw-imagerie\">IRM annuelle</span></li></ul><p><strong>Carcinome hépatocellulaire (CHC)</strong></p><p>décision en <span class=\"kw-ttt\">RCP</span></p><ul><li>Curatif : <span class=\"kw-ttt\">ablation percutanée</span>, <span class=\"kw-ttt\">résection chirurgicale</span>, <span class=\"kw-ttt\">transplantation hépatique</span></li><li>Palliatif : <span class=\"kw-ttt\">chimio-embolisation (TACE)</span>, <span class=\"kw-ttt\">thérapies ciblées anti-angiogéniques</span>, <span class=\"kw-ttt\">immunothérapie</span>, soins de confort</li></ul><p><strong>Cholangiocarcinome</strong></p><ul><li>Curatif : <span class=\"kw-ttt\">résection chirurgicale</span> (seul traitement curatif) + <span class=\"kw-ttt\">chimiothérapie adjuvante</span></li><li>Non résécable : <span class=\"kw-ttt\">chimiothérapie</span> ± <span class=\"kw-ttt\">radiothérapie</span></li><li>Palliatif : <span class=\"kw-ttt\">drainage biliaire</span> (CPRE / prothèse / drain) pour l’<span class=\"kw-clinique\">ictère</span> et le <span class=\"kw-clinique\">prurit</span></li></ul><p><strong>Métastases hépatiques</strong></p><ul><li>PEC dépendante du <span class=\"kw-etio\">cancer primitif</span> : le plus souvent <span class=\"kw-ttt\">thérapie systémique</span> ou traitement palliatif</li><li>Métastases de <span class=\"kw-etio\">cancer colorectal</span> = les plus accessibles à un <span class=\"kw-ttt\">traitement curatif</span></li></ul>","suivi":"<p><strong><span class=\"kw-bio\">AFP</span> :</strong> l’<span class=\"kw-bio\">α-fœtoprotéine</span> a une <strong>valeur pronostique</strong> — ce n’est pas un examen diagnostique du <span class=\"kw-def\">CHC</span>.</p><p><strong>Dépistage du CHC</strong></p><p>à poursuivre même après contrôle / éradication de la cause (risque persistant)</p><ul><li><span class=\"kw-etio\">Cirrhose</span> : <span class=\"kw-imagerie\">échographie abdominale</span> + <span class=\"kw-bio\">α-fœtoprotéine</span> tous les <span class=\"kw-chiffre\">6 mois</span></li><li><span class=\"kw-etio\">Hépatite B</span> sans cirrhose : <span class=\"kw-imagerie\">échographie</span> tous les <span class=\"kw-chiffre\">2 ans</span></li></ul><p><strong>Surveillance de l’adénome hépatocytaire</strong></p><ul><li>Tumeur <span class=\"kw-chiffre\">&lt; 5 cm</span> chez la femme : <span class=\"kw-imagerie\">IRM annuelle</span></li><li><span class=\"kw-ttt\">Arrêt des œstrogènes</span> dans tous les cas</li></ul>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/liver-tumours","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/simple-hepatic-cyst","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/hepatic-haemangioma-3","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/hepatocellular-carcinoma","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/hepatic-metastases-1","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/cholangiocarcinoma","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Tumeur hépatique découverte — Signes cliniques · anomalie du bilan hépatique · découverte fortuite en imagerie. 1re question : maladie chronique du foie ? (clinique, biologie, échographie, élastométrie / Fibroscan)","detail":"<h4>CAT — démarche diagnostique devant une tumeur du foie — Du contexte (foie chronique ?) à la sémiologie en imagerie</h4>","branches":[{"to":"t-chc","label":"Oui — cirrhose / hépatopathie chronique","color":"red"},{"to":"q-kyst-solide","label":"Non — foie sain (pas d’hépatopathie chronique)","color":"green"}]},{"id":"t-chc","kind":"terminal","label":"Carcinome hépatocellulaire (CHC)","color":"red","detail":"<h4>Contexte</h4><ul><li><span class=\"kw-def\">CHC</span> = cancer primitif du foie le plus fréquent, développé sur <span class=\"kw-etio\">maladie chronique du foie</span> dans <span class=\"kw-chiffre\">90 %</span> des cas (<span class=\"kw-etio\">alcool</span>-<span class=\"kw-etio\">VHC</span> en Europe, <span class=\"kw-etio\">VHB</span> en Afrique-Asie)</li><li>Vascularisé exclusivement par l’artère hépatique</li></ul><h4>Imagerie (<span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">IRM</span> multiphasique)</h4><ul><li>Sans injection : nodule iso / hypodense</li><li>Temps artériel : <span class=\"kw-imagerie\">wash-in</span> (rehaussement intense)</li><li>Temps portal : <span class=\"kw-imagerie\">wash-out</span> (lavage)</li></ul><h4>Diagnostic</h4><ul><li>Nodule <span class=\"kw-chiffre\">&gt; 1 cm</span> avec <span class=\"kw-imagerie\">wash-in + wash-out</span> sur <span class=\"kw-etio\">cirrhose certaine</span>, validé en <span class=\"kw-ttt\">RCP</span> → <span class=\"kw-imagerie\">biopsie</span> non indispensable ; sinon biopsie écho-guidée (couplée à une biopsie en foie normal)</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">α-fœtoprotéine</span> = valeur pronostique (pas un examen diagnostique)</li></ul><h4>PEC</h4><ul><li>Curatif (<span class=\"kw-ttt\">ablation</span> / <span class=\"kw-ttt\">résection</span> / <span class=\"kw-ttt\">transplantation</span>) ou palliatif (<span class=\"kw-ttt\">TACE</span>, <span class=\"kw-ttt\">thérapies ciblées</span>, <span class=\"kw-ttt\">immunothérapie</span>) — voir rubrique Principes</li></ul>"},{"id":"q-kyst-solide","kind":"decision","label":"Lésion kystique ou solide à l’imagerie ? — Confrontation clinique / sémiologie radiologique","branches":[{"to":"q-kyste","label":"Lésion kystique (liquidienne)","color":"blue"},{"to":"q-pdc","label":"Lésion solide (même partiellement liquidienne)","color":"blue"}]},{"id":"q-kyste","kind":"decision","label":"Kyste typique ou suspect ? — Paroi · cloisons · contexte d’endémie","branches":[{"to":"t-kyste-biliaire","label":"Parfaitement liquidienne, sans paroi ni cloison","color":"green"},{"to":"t-kyste-hydatique","label":"Paroi / cloisons + zone d’endémie (contact chien)","color":"amber"}]},{"id":"t-kyste-biliaire","kind":"terminal","label":"Kyste biliaire simple","color":"green","detail":"<h4>Définition</h4><ul><li>Paroi unicellulaire d’épithélium biliaire, contenu liquidien clair (pas de bile), ne communique pas avec l’arbre biliaire</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie</span> : anéchogène + cône de renforcement postérieur</li><li><span class=\"kw-imagerie\">TDM</span> : hypodense ; <span class=\"kw-imagerie\">IRM</span> : hyperT2</li></ul><h4>PEC</h4><ul><li><span class=\"kw-ttt\">Abstention</span> ; <span class=\"kw-ttt\">fenestration</span> seulement si complication mécanique. <span class=\"kw-imagerie\">Biopsie</span> inutile</li></ul>"},{"id":"t-kyste-hydatique","kind":"terminal","label":"Kyste hydatique","color":"amber","detail":"<h4>Contexte</h4><ul><li>Sujet ayant vécu en <span class=\"kw-etio\">zone d’endémie</span> au contact de <span class=\"kw-etio\">chiens</span></li></ul><h4>Diagnostic</h4><ul><li>Lésion kystique à paroi / cloisons (≠ kyste biliaire simple) → <span class=\"kw-bio\">sérologies d’hydatidose</span></li></ul>"},{"id":"q-pdc","kind":"decision","label":"Cinétique du rehaussement après injection (PDC) ? — Comportement aux temps artériel et portal","branches":[{"to":"t-hemangiome","label":"Mottes périphériques, remplissage centripète","color":"green"},{"to":"t-abces","label":"Rehaussement périphérique artériel, centre non rehaussé","color":"amber"},{"to":"t-metastase","label":"Absence de rehaussement (artériel et portal) ou rehaussement sans wash-out","color":"red"},{"to":"q-washout","label":"Rehaussement net au temps artériel + wash-out","color":"amber"}]},{"id":"t-hemangiome","kind":"terminal","label":"Hémangiome (angiome)","color":"green","detail":"<h4>Définition</h4><ul><li>Malformation vasculaire (capillaires dilatés) ; tumeur bénigne la plus fréquente (<span class=\"kw-chiffre\">3-5 %</span>), prédominance féminine</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie</span> : hyperéchogène + renforcement postérieur (peut suffire au diagnostic)</li><li><span class=\"kw-imagerie\">TDM / IRM</span> : remplissage en mottes périphériques, centripète (du temps artériel au tardif)</li></ul><h4>PEC</h4><ul><li><span class=\"kw-ttt\">Abstention</span> : ne dégénère jamais, pas de surveillance. <span class=\"kw-imagerie\">Biopsie</span> <span class=\"kw-ci\">contre-indiquée</span> (risque hémorragique)</li></ul>"},{"id":"t-abces","kind":"terminal","label":"Abcès / tumeur nécrosée","color":"amber","detail":"<h4>Imagerie</h4><ul><li>Rehaussement périphérique au temps artériel, centre non rehaussé</li></ul><h4>À évoquer</h4><ul><li><span class=\"kw-etio\">Abcès à pyogènes</span> (rare) ou <span class=\"kw-etio\">abcès amibien</span> : <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">douleur</span></li><li>Ou tumeur solide nécrosée</li></ul>"},{"id":"t-metastase","kind":"terminal","label":"Métastase hépatique","color":"red","detail":"<h4>Contexte</h4><ul><li>Tumeur maligne du foie la plus fréquente ; primitifs (ordre) : <span class=\"kw-etio\">adénocarcinomes digestifs</span> (estomac, pancréas, côlon, rectum) &gt; <span class=\"kw-etio\">poumon</span> &gt; <span class=\"kw-etio\">sein</span></li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie</span> : images hypoéchogènes en cocardes</li><li><span class=\"kw-imagerie\">TDM</span> : hypodense, pas de rehaussement au temps artériel, couronne périphérique au temps portal</li></ul><h4>Diagnostic</h4><ul><li>Caractère <strong>multiple</strong> = argument fort. <span class=\"kw-imagerie\">Biopsie</span> inutile si primitif connu + métastases &lt; <span class=\"kw-chiffre\">2 ans</span> + imagerie compatible ; nécessaire si métachrone <span class=\"kw-chiffre\">&gt; 2 ans</span>, imagerie atypique ou primitif inconnu</li></ul><h4>PEC</h4><ul><li>Dépend du primitif ; métastases de <span class=\"kw-etio\">cancer colorectal</span> = les plus accessibles à un <span class=\"kw-ttt\">traitement curatif</span></li></ul>"},{"id":"q-washout","kind":"decision","label":"Cicatrice centrale ou terrain œstrogénique ? — Sur foie sain — distinguer HNF et adénome","branches":[{"to":"t-hnf","label":"Cicatrice fibreuse centrale stellaire (hyperT2), femme jeune","color":"green"},{"to":"t-adenome","label":"Lésion hétérogène, femme sous œstrogènes (ou homme)","color":"amber"}]},{"id":"t-hnf","kind":"terminal","label":"Hyperplasie nodulaire focale (HNF)","color":"green","detail":"<h4>Définition</h4><ul><li>Tumeur bénigne ne recevant que du sang artériel, avec cicatrice fibreuse centrale stellaire ; femme jeune</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie</span> : iso / hypoéchogène (diagnostic difficile)</li><li><span class=\"kw-imagerie\">TDM / IRM</span> : rehaussement intense au temps artériel + cicatrice centrale (hyperT2)</li></ul><h4>PEC</h4><ul><li><span class=\"kw-ttt\">Abstention</span> : ne se complique jamais, ni traitement ni surveillance. <span class=\"kw-imagerie\">Biopsie</span> possible si doute</li></ul>"},{"id":"t-adenome","kind":"terminal","label":"Adénome hépatocytaire","color":"amber","detail":"<h4>Définition</h4><ul><li>Prolifération d’hépatocytes monoclonaux : <span class=\"kw-alerte\">potentiel de dégénérescence maligne</span> et <span class=\"kw-alerte\">hémorragipare</span> (risque de rupture) ; favorisé par les <span class=\"kw-etio\">œstrogènes</span> (COP), femme (<span class=\"kw-chiffre\">75 %</span>)</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie</span> : nodule hétérogène, hypoéchogène</li><li><span class=\"kw-imagerie\">TDM</span> : wash-in / wash-out ; <span class=\"kw-imagerie\">IRM</span> : rehaussement hétérogène au temps artériel</li></ul><h4>Diagnostic</h4><ul><li><span class=\"kw-imagerie\">Biopsie</span> nécessaire (diagnostic différentiel avec un CHC bien différencié ou une HNF)</li></ul><h4>PEC</h4><ul><li><span class=\"kw-ttt\">Chirurgie</span> si <span class=\"kw-chiffre\">&gt; 5 cm</span>, sexe masculin ou mutation β-caténine ; sinon <span class=\"kw-ttt\">arrêt des œstrogènes</span> + <span class=\"kw-imagerie\">IRM annuelle</span></li></ul>"}]},"cards":[{"i":"0074d15d9a0b","n":304,"o":"304-10","u":"Diagnostic positif","t":"Connaître la présentation clinique des tumeurs biliaires","q":"Quelle est l'approche diagnostique initiale devant une suspicion de cholangiocarcinome (CCA) ?","a":"<p>La première imagerie à réaliser est l'<strong>échographie hépato-biliaire</strong>. Elle permet d'évoquer le diagnostic en montrant :</p><ul><li>Un <strong>syndrome de masse hépatique</strong>.</li><li>Une <strong>dilatation des voies biliaires d'amont</strong>.</li></ul><p>Devant tout <strong>ictère cholestatique à bilirubine conjuguée</strong> associé à une <strong>dilatation des voies biliaires</strong>, il faut impérativement évoquer et rechercher un <strong>obstacle tumoral</strong>. Le <strong>CCA hilaire (tumeur de Klatskin)</strong> est le diagnostic à éliminer en priorité chez l'adulte de <strong>plus de 50 ans</strong>.</p>"},{"i":"a03837aaf198","n":304,"o":"304-10","u":"Diagnostic positif","t":"Connaître la présentation clinique des tumeurs biliaires","q":"Quelle est la présentation clinique spécifique des tumeurs biliaires (CCA) extra-hépatiques ?","a":"<p>Les CCA extra-hépatiques se manifestent principalement par un <strong>ictère cholestatique</strong>, à bilirubine conjuguée. Cet ictère se traduit par la triade classique :</p><ul><li><strong>Prurit</strong></li><li><strong>Selles décolorées (acholiques)</strong></li><li><strong>Urines foncées (bilirubinurie)</strong></li></ul>"},{"i":"e43718e4915f","n":304,"o":"304-10","u":"Diagnostic positif","t":"Connaître la présentation clinique des tumeurs biliaires","q":"Comment se présentent cliniquement les tumeurs biliaires (CCA), en particulier les CCA intra-hépatiques ?","a":"<p>Le <strong>cholangiocarcinome (CCA)</strong> peut se révéler de différentes manières :</p><ul><li><strong>Découverte fortuite</strong>, très fréquente pour les CCA intra-hépatiques, souvent sur une imagerie réalisée pour une autre raison.</li><li><strong>Signes généraux</strong> non spécifiques : altération de l'état général (AEG), fièvre, hépatalgie.</li></ul>"},{"i":"0127da47686f","n":304,"o":"304-3","u":"Étiologies","t":"Connaître la liste des principales hépatopathies augmentant le risque de survenue ultérieure d’un cancer primitif du foie","q":"Quelles sont les principales causes de cirrhose en Europe augmentant le risque de carcinome hépatocellulaire (CHC) ?","a":"<ul><li>La consommation chronique d'<strong>alcool</strong>.</li><li>L'<strong>hépatite virale C chronique</strong> (VHC).</li></ul>"},{"i":"118438c199d7","n":304,"o":"304-3","u":"Étiologies","t":"Connaître la liste des principales hépatopathies augmentant le risque de survenue ultérieure d’un cancer primitif du foie","q":"Quel est le risque annuel de développer un carcinome hépatocellulaire (CHC) sur une cirrhose hépatique ?","a":"<p>Le risque annuel de développer un carcinome hépatocellulaire (CHC) sur une cirrhose hépatique est de <strong>2 à 5 % par an</strong>, soit 5 à 30 % à 5 ans.</p>"},{"i":"2dca69292c88","n":304,"o":"304-3","u":"Étiologies","t":"Connaître la liste des principales hépatopathies augmentant le risque de survenue ultérieure d’un cancer primitif du foie","q":"Quelles hépatopathies peuvent entraîner un carcinome hépatocellulaire (CHC) même en l'absence de cirrhose préalable ?","a":"<ul><li>L'<strong>hépatite virale B chronique</strong> (VHB).</li><li>L'<strong>hémochromatose</strong>.</li><li>La <strong>stéato-hépatite métabolique</strong> (NASH).</li></ul>"},{"i":"4d4bd9d2e5d4","n":304,"o":"304-3","u":"Étiologies","t":"Connaître la liste des principales hépatopathies augmentant le risque de survenue ultérieure d’un cancer primitif du foie","q":"Pourquoi le dépistage du carcinome hépatocellulaire (CHC) doit-il être maintenu chez un patient cirrhotique, même après contrôle de la cause sous-jacente ?","a":"<p>Le dépistage du carcinome hépatocellulaire (CHC) doit être maintenu car le <strong>risque persiste</strong> même après l'éradication virale (VHB/VHC) ou le sevrage alcoolique chez tout patient cirrhotique.</p>"},{"i":"a72fd90440a3","n":304,"o":"304-3","u":"Étiologies","t":"Connaître la liste des principales hépatopathies augmentant le risque de survenue ultérieure d’un cancer primitif du foie","q":"Quelle est l'hépatopathie la plus fréquemment associée au carcinome hépatocellulaire (CHC) en Occident ?","a":"<p>En Occident, le carcinome hépatocellulaire (CHC) se développe sur une <strong>maladie chronique du foie</strong> dans 90 % des cas, principalement la <strong>cirrhose hépatique</strong> quelle qu'en soit la cause.</p>"},{"i":"1f74332db2e7","n":304,"o":"304-4","u":"Diagnostic positif","t":"Connaître la démarche diagnostique initiale","q":"Quelle est la démarche diagnostique si une tumeur hépatique est découverte chez un patient sans hépatopathie chronique connue ?","a":"<p>Si une tumeur hépatique est découverte chez un patient <strong>sans hépatopathie chronique connue</strong>, on réalise un <strong>Scanner ou IRM hépatique multiphasique avec une gamme diagnostique large</strong>.</p><p>Les diagnostics possibles incluent : angiome, métastase, hyperplasie nodulaire focale (HNF), carcinome hépatocellulaire (moins fréquent sans cirrhose), cholangiocarcinome, ou adénome hépatique. Si l'imagerie n'est pas concluante, une <strong>biopsie de la lésion</strong> est alors nécessaire.</p>"},{"i":"512447ee0700","n":304,"o":"304-4","u":"Diagnostic positif","t":"Connaître la démarche diagnostique initiale","q":"Quelle est la question pivot initiale dans la démarche diagnostique d'une tumeur hépatique ?","a":"<p>La question pivot initiale est : <strong>« Le patient a-t-il une maladie chronique du foie ? »</strong></p><p>Cette évaluation se fait par un examen clinique, un bilan biologique hépatique, une échographie et/ou une élastométrie (Fibroscan).</p>"},{"i":"c3d496692252","n":304,"o":"304-4","u":"Diagnostic positif","t":"Connaître la démarche diagnostique initiale","q":"Dans quelles circonstances peut-on découvrir une tumeur hépatique ?","a":"<p>On peut découvrir une tumeur hépatique dans trois circonstances principales :</p><ul><li>Suite à des <strong>signes cliniques</strong> (douleurs, hépatomégalie).</li><li>Devant des <strong>anomalies du bilan hépatique</strong> (élévation des transaminases, de la bilirubine, ou de l'alpha-fœtoprotéine - AFP).</li><li>Par <strong>découverte fortuite</strong> lors d'une imagerie (échographie, TDM, IRM) pour une autre raison.</li></ul>"},{"i":"e59ee3f086d8","n":304,"o":"304-4","u":"Diagnostic positif","t":"Connaître la démarche diagnostique initiale","q":"Quelle est la prise en charge diagnostique d'une tumeur hépatique en cas de cirrhose ou hépatopathie chronique connue ?","a":"<p>En cas de <strong>cirrhose ou hépatopathie chronique connue</strong>, la démarche inclut un <strong>Scanner ou IRM hépatique multiphasique</strong>.</p><p>Deux principales hypothèses sont envisagées :</p><ul><li>Le <strong>carcinome hépatocellulaire (CHC)</strong>, qui est le plus fréquent dans ce contexte.</li><li>Une autre tumeur, plus rare.</li></ul><p>Le diagnostic de CHC peut être posé <strong>sans biopsie</strong> si les <strong>critères AASLD-EASL</strong> sont réunis : nodule &gt; 1 cm avec <strong>wash-in et wash-out</strong>, chez un patient avec cirrhose certaine, et validation en RCP (réunion de concertation pluridisciplinaire).</p>"},{"i":"f5cb1baea153","n":304,"o":"304-4","u":"Diagnostic positif","t":"Connaître la démarche diagnostique initiale","q":"Comment interpréter le dosage de l'alpha-fœtoprotéine (AFP) dans le diagnostic des tumeurs hépatiques, en particulier du CHC ?","a":"<p>Le dosage de l'<strong>alpha-fœtoprotéine (AFP) n'est PAS un examen diagnostique du carcinome hépatocellulaire (CHC)</strong>.</p><p>C'est un <strong>marqueur pronostique</strong> ou de suivi post-thérapeutique. Le diagnostic repose principalement sur l'imagerie, parfois complétée par une biopsie.</p>"},{"i":"079cd72dd649","n":304,"o":"304-7","u":"Diagnostic positif","t":"Connaître la présentation clinique d’une tumeur primitive du foie","q":"Quels sont les signes fonctionnels les plus fréquemment rencontrés lors de la présentation clinique d'un carcinome hépatocellulaire (CHC) ?","a":"<ul><li><strong>Douleurs de l'hypochondre droit</strong></li><li>Pesanteur épigastrique</li><li><strong>Altération de l'état général (AEG)</strong> : asthénie, anorexie, amaigrissement</li><li>Fièvre</li><li>Anémie</li></ul>"},{"i":"6450112b8efe","n":304,"o":"304-7","u":"Diagnostic positif","t":"Connaître la présentation clinique d’une tumeur primitive du foie","q":"En présence de quel facteur de risque principal met-on en place un dépistage du carcinome hépatocellulaire (CHC) et selon quelles modalités ?","a":"<p>Le dépistage du CHC est mis en place principalement en présence d'une <strong>cirrhose</strong>. Les modalités sont une <strong>échographie abdominale et un dosage de l'alpha-fœtoprotéine tous les 6 mois</strong>. En cas d'hépatite B sans cirrhose, une échographie abdominale tous les 2 ans est recommandée.</p>"},{"i":"7f3217c339e5","n":304,"o":"304-7","u":"Diagnostic positif","t":"Connaître la présentation clinique d’une tumeur primitive du foie","q":"Quelle est la présentation épidémiologique typique d'un carcinome hépatocellulaire (CHC) en Occident ?","a":"<p>En Occident, le CHC se présente typiquement chez un sujet de <strong>plus de 45 ans</strong>, avec une nette <strong>prédominance masculine</strong> (sex-ratio 6:1), et dans <strong>90% des cas sur cirrhose</strong>.</p>"},{"i":"8c70c45fd812","n":304,"o":"304-7","u":"Diagnostic positif","t":"Connaître la présentation clinique d’une tumeur primitive du foie","q":"Comment un carcinome hépatocellulaire (CHC) peut-il se révéler par une décompensation de cirrhose ?","a":"<p>Un CHC peut se révéler par une <strong>décompensation œdémato-ascitique</strong>, une <strong>hémorragie digestive</strong> par rupture de varices œsophagiennes, ou une <strong>aggravation d'une insuffisance hépatocellulaire (IHC) et/ou d'une hypertension portale (HTP)</strong> déjà connues.</p>"},{"i":"a88a10e1c211","n":304,"o":"304-7","u":"Diagnostic positif","t":"Connaître la présentation clinique d’une tumeur primitive du foie","q":"Citez des exemples de syndromes paranéoplasiques pouvant être associés à un carcinome hépatocellulaire (CHC).","a":"<ul><li><strong>Polyglobulie</strong> (par sécrétion d'EPO)</li><li><strong>Hypoglycémie</strong> (par sécrétion d'insuline)</li><li>Hypercalcémie</li></ul>"},{"i":"f04c34297542","n":304,"o":"304-7","u":"Diagnostic positif","t":"Connaître la présentation clinique d’une tumeur primitive du foie","q":"Quels sont les signes physiques à rechercher à l'examen clinique pouvant évoquer un carcinome hépatocellulaire (CHC) ?","a":"<ul><li><strong>Hépatomégalie ferme et nodulaire</strong></li><li>Ictère</li><li>Ascite</li></ul>"}]};